#!/usr/bin/env python3
"""Colab FINAL test for the TMT gpu_port — generated by make_colab_bundle.py.
Self-contained: unpacks the repo modules next to itself, then runs the gate.
"""
import base64, gzip, os, sys, time

HERE = os.path.dirname(os.path.abspath(__file__)) if "__file__" in globals() else os.getcwd()
if not os.path.isdir(HERE):
    HERE = "/content" if os.path.isdir("/content") else os.getcwd()
PAYLOAD = {'gpu_port.py': '', 'train_gpu.py': '', 'numpy_port.py': '', 'tail_credit.py': '', 'checkpoint_hub.py': ''}

for name, b64 in PAYLOAD.items():
    p = os.path.join(HERE, name)
    with open(p, "wb") as f:
        f.write(gzip.decompress(base64.b64decode(b64)))
sys.path.insert(0, HERE)

import numpy as np
import torch
import gpu_port
from gpu_port import GpuModel
import train_gpu as tg

CKPT = "synth.npz"
STEPS = 20
FAILS = []

def result(name, ok, detail=""):
    tag = "PASS" if ok else "FAIL"
    print(f"[RESULT] {name}: {tag} {detail}", flush=True)
    if not ok:
        FAILS.append(name)

def banner(s):
    print(f"\n===== {s} =====", flush=True)

# ---------------- A: environment ----------------
banner("A: environment")
print("python", sys.version.split()[0], "| torch", torch.__version__, flush=True)
cuda = torch.cuda.is_available()
print("cuda_available", cuda, "| device",
      torch.cuda.get_device_name(0) if cuda else "cpu",
      "| vram_GB", round(torch.cuda.get_device_properties(0).total_memory / 1e9, 1)
      if cuda else 0.0, flush=True)
if not cuda:
    print("[RESULT] OVERALL = FAIL (no CUDA)"); sys.exit(1)

# ---------------- B: bench ----------------
banner("B: bench (fresh init, fp32, no TF32)")
m = GpuModel(dim=512, layers=16, device="cuda")
cs = torch.randint(1, 250, (4096,), device="cuda")
ns = torch.randint(1, 250, (4096,), device="cuda")
ends = torch.zeros(4096, dtype=torch.float32, device="cuda")
bench = {}
for B in (1024, 2048, 4096):
    m.new_states(B)
    for _ in range(4):
        m.step_batch(cs[:B], ns[:B], ends[:B])
    torch.cuda.synchronize()
    t0 = time.time(); N = 40
    for _ in range(N):
        m.step_batch(cs[:B], ns[:B], ends[:B])
    torch.cuda.synchronize()
    dt = (time.time() - t0) / N
    bench[B] = B / dt
    print(f"[RESULT] bench B={B}: {1/dt:.1f} steps/s = {B/dt:,.0f} B/s "
          f"({dt*1000:.1f} ms/step)", flush=True)
# speed is a measurement, not a correctness gate: reported, never FAILs
print(f"[RESULT] bench summary: B=1024 {bench[1024]:,.0f} B/s | "
      f"B=2048 {bench[2048]:,.0f} B/s | B=4096 {bench[4096]:,.0f} B/s", flush=True)

# ---------------- C: synthetic checkpoint with hot dims (tail on GPU) ----
banner("C: synthetic checkpoint (12 hot dims/layer) -> CUDA vs CPU torch")
def make_model(dev):
    mm = GpuModel(dim=512, layers=16, device=dev)
    for l in mm.layers:
        for j in range(12):
            l.decay[j] = 4.0
    mm.new_states(1024)
    return mm

warm = make_model("cpu")
warm_t = torch.randint(1, 250, (10, 1024))
warm_n = torch.randint(1, 250, (10, 1024))
warm_e = torch.zeros(10, 1024, dtype=torch.float32)
for t in range(10):
    warm.step_batch(warm_t[t], warm_n[t], warm_e[t])
hot = sum(warm.tail.nhot(i) for i in range(16))
warm.save(CKPT)
print(f"  synth ckpt: t={warm.t} ring_k={warm.ring_k} hot_dims={hot}", flush=True)
result("synth-hot-dims", hot >= 180, f"{hot} hot dims")

cpu_m = make_model("cpu"); cpu_m.load(CKPT)
gpu_m = make_model("cuda"); gpu_m.load(CKPT)
result("tail-load-cuda", sum(gpu_m.tail.nhot(i) for i in range(16)) == hot,
       f"cuda hot dims {sum(gpu_m.tail.nhot(i) for i in range(16))}")

rng = np.random.default_rng(5)
cs_n = rng.integers(1, 250, (STEPS, 1024))
ns_n = rng.integers(1, 250, (STEPS, 1024))
# CPU leg
cpu_m = make_model("cpu"); cpu_m.load(CKPT)
lc = []
for t in range(STEPS):
    e = torch.zeros(1024, dtype=torch.float32)
    lc.append(cpu_m.step_batch(torch.from_numpy(cs_n[t]), torch.from_numpy(ns_n[t]), e))
# CUDA leg (same bytes)
gpu_m = make_model("cuda"); gpu_m.load(CKPT)
lg = []
for t in range(STEPS):
    e = torch.zeros(1024, dtype=torch.float32, device="cuda")
    lg.append(gpu_m.step_batch(torch.from_numpy(cs_n[t]).to("cuda"),
                               torch.from_numpy(ns_n[t]).to("cuda"), e))
maxrel = max(abs(a - b) / max(1.0, abs(a)) for a, b in zip(lc, lg))
print(f"[RESULT] CUDA-vs-CPU maxrel loss over {STEPS} steps: {maxrel:.3e}", flush=True)
for t in range(STEPS):
    print(f"  step {cpu_m.t - STEPS + t + 1:6d}: cpu {lc[t]:.6f} cuda {lg[t]:.6f}",
          flush=True)
result("cuda-parity", maxrel < 1e-3, f"maxrel {maxrel:.2e}")

# ---------------- D: tagged save / reload / continue on CUDA --------------
banner("D: save/reload/continue on CUDA")
gpu_m.save("synth_gpu.npz")
m2 = make_model("cuda"); m2.load("synth_gpu.npz")
c = torch.from_numpy(cs_n[0]).to("cuda"); n = torch.from_numpy(ns_n[0]).to("cuda")
e = torch.zeros(1024, dtype=torch.float32, device="cuda")
lb = gpu_m.step_batch(c, n, e)
la = m2.step_batch(c, n, e)
rel = abs(lb - la) / max(1.0, abs(lb))
print(f"  continue 1 step: {lb:.6f} vs {la:.6f} (rel {rel:.2e})", flush=True)
result("gpu-roundtrip", rel < 1e-6 and m2.t == gpu_m.t, f"rel {rel:.2e}")

# ---------------- E: train_gpu end-to-end on GPU ------------------------
banner("E: train_gpu.py tagged-save smoke on GPU")
with open("tiny_corpus.txt", "w") as f:
    for i in range(2000):
        f.write("The quick brown fox jumps over the lazy dog. Line %d.\n" % i)
tr = tg.Trainer(path="tiny.npz", batch=256, save_every=15, keep_k=2,
                max_steps=30, device="cuda", dim=512, layers=16, lr=5e-4)
tr.train(True, "tiny_corpus.txt")
tags = [x for x in os.listdir(HERE) if x.startswith("tmt_t")]
result("trainer-gpu", len(tags) >= 2 and os.path.exists("tiny.npz"),
       f"tags {tags}")

# ---------------- verdict ----------------
print(f"\n[RESULT] OVERALL = {'FAIL ' + str(FAILS) if FAILS else 'PASS'}", flush=True)
sys.exit(1 if FAILS else 0)
